 typ='cross_text_synthesis' if s.get('pair') and s['id'].endswith('p04') else 'summary';prompt='Compare les deux positions sur l’usage d’une prévision pour décider.' if typ=='cross_text_synthesis' else 'Résume le raisonnement du passage.';ans=s.get('across',s['asummary'])
