def mk(s,forms,reviews,prior,deck,lo,hi,theme):
 ps=list(s['paras']);ps[1]+=' '+' '.join(USE[f] for f in forms);ps[2]+=' '+bridge(reviews);ps,text=fit(ps,lo,hi);P=base.prior(prior);new=[base.nt(f,text,deck) for f in forms];rev=[base.rev(f,P) for f in reviews];ids={t['form']:t['id'] for t in new+rev};q,a=base.qa(qs(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C1','unit':8,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':'instructional','genre':s['genre'],'domains':['professional','public'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'new','description':'qualify horizon, quantity, counterfactual and conditional forecast claims'}],'discourse_targets':[{'id':s['id']+'-d1','role':'new','description':'connect forecast, uncertainty, alternative scenario, distributional consequence and revision rule'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C1 Unit08 risk/forecasting.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Fictional economic/forecasting cases.']},'paired_text_group':s.get('pair'),'prerequisites':['French C1 Unit07'],'difficulty_notes_internal':'C1 forecast calibration, sensitivity and decision under risk.','reader_tags':['unit_role:instructional','generation_batch','french_c1_u08']}
def specs():return [
 {'id':'fr-c1-u08-p01','seq':43,'title':'Une prévision change quand son horizon change','genre':'briefing','topics':['forecast horizon','timeliness'],'paras':["Un service fictif doit prévoir la demande d’un réseau de transport. Le même modèle produit une estimation pour le lendemain, la semaine suivante et le trimestre suivant. Le rapport refuse de présenter ces trois nombres comme s’ils possédaient la même qualité : les variables observables et les sources d’erreur se déplacent avec l’horizon.","Pour l’horizon proche, l’information opérationnelle récente domine; pour l’horizon long, des hypothèses sur comportement, calendrier et capacité deviennent plus importantes. Le texte compare aussi le coût de retarder la décision afin d’obtenir une mesure plus précise.","L’objection affirme qu’une seule prévision centrale est plus simple à communiquer. Le briefing répond qu’une simplicité qui cache les horizons peut produire une erreur de décision : un nombre correct pour demain peut être inutilisable pour un investissement de plusieurs mois.","La recommandation associe chaque décision à son horizon, à un intervalle plausible et à une date d’actualisation. Le modèle n’est donc pas jugé par une précision abstraite, mais par la relation entre le moment prévu, le moment de la décision et la possibilité de corriger."],'qclaim':'Quelle thèse organise le briefing ?','aclaim':'La qualité d’une prévision dépend de l’horizon et du moment de la décision, pas seulement d’un nombre central.','qinfer':'Pourquoi une donnée récente perd-elle parfois de l’importance à long terme ?','ainfer':'Parce que d’autres hypothèses et changements structurels deviennent dominants.','qassume':'Que suppose une comparaison entre horizons ?','aassume':'Que les variables, erreurs et décisions associées à chaque horizon soient explicitement distinguées.','qrelation':'Comment le texte répond-il à l’argument de simplicité ?','arelation':'Il montre qu’un seul nombre peut simplifier la présentation tout en mélangeant des décisions de temporalité différente.','astance':'Adapter la prévision à l’horizon et au coût du délai.','asummary':'Une prévision utile indique quand elle s’applique, quand elle doit être actualisée et quelle décision elle peut réellement éclairer.'},
 {'id':'fr-c1-u08-p02','seq':44,'title':'Un seuil transforme parfois une petite différence en grande décision','genre':'analysis','topics':['thresholds','base rates'],'paras':["Une organisation fictive classe un indicateur en trois niveaux selon deux seuils. Deux observations presque identiques peuvent donc recevoir des étiquettes différentes si elles se trouvent de part et d’autre d’une frontière. L’analyse demande si cette rupture catégorielle correspond à une différence réelle de conséquence.","Le rapport reconstruit la quantité brute, la base de comparaison et l’incertitude. Il distingue également une différence statistique d’une différence suffisamment grande pour modifier une décision. Le mot qui réduit ou amplifie un nombre devient lui-même un objet d’examen lorsque la référence n’est pas annoncée.","Le contreargument soutient qu’une institution a besoin de seuils pour agir de manière cohérente. Le texte accepte la nécessité opérationnelle, mais propose une zone de révision autour de la frontière et une justification fondée sur le coût des deux erreurs possibles.","La conclusion conserve les seuils tout en refusant de les traiter comme des propriétés naturelles des données. Ils sont des règles de décision qui doivent être testées, documentées et modifiées si les conséquences observées ne correspondent plus à l’objectif."],'qclaim':'Quel problème les seuils créent-ils ?','aclaim':'Ils peuvent transformer une variation continue faible en catégorie décisionnelle distincte sans que la conséquence change autant.','qinfer':'Pourquoi la base de comparaison est-elle nécessaire ?','ainfer':'Parce qu’une quantité peut paraître grande ou faible selon la référence utilisée.','qassume':'Que suppose un seuil défendable ?','aassume':'Un lien explicite entre la frontière choisie et le coût des décisions qu’elle déclenche.','qrelation':'Comment le texte traite-t-il le besoin de cohérence ?','arelation':'Il garde des seuils mais ajoute une zone de révision et une justification par les erreurs possibles.','astance':'Traiter les seuils comme des outils révisables plutôt que des faits naturels.','asummary':'La quantité, la référence et le coût des erreurs doivent être visibles avant qu’un seuil transforme une mesure en décision.'},
 {'id':'fr-c1-u08-p03','seq':45,'title':'Point de vue A : décider avec une valeur attendue explicite','genre':'scenario comparison','topics':['expected value','work and value'],'pair':PAIR,'paras':["Le premier point de vue compare deux programmes fictifs qui promettent des bénéfices différents pour des coûts incertains. Il propose de rendre explicite une valeur attendue : plusieurs scénarios sont pondérés par leurs probabilités afin d’éviter qu’un cas spectaculaire domine toute la discussion.","Cette méthode oblige à préciser les montants, les personnes concernées et la période. Une somme élevée n’est pas automatiquement un mauvais investissement; elle doit être comparée aux bénéfices, aux alternatives et aux ressources qui auraient été utilisées autrement.","Le contreargument affirme que la moyenne pondérée peut cacher des pertes concentrées. Le point de vue A l’accepte et ajoute des contraintes : certains dommages sont traités séparément de la valeur moyenne, et la recommandation doit montrer la distribution des résultats.","La conclusion défend la valeur attendue comme point de départ contrôlable, non comme réponse mécanique. Elle permet de rendre les hypothèses numériques visibles avant d’ajouter des considérations de distribution, de réversibilité et de capacité."],'qclaim':'Quelle méthode défend le point de vue A ?','aclaim':'Rendre explicites scénarios, probabilités et valeurs afin de comparer les options sur une base commune.','qinfer':'Pourquoi un coût élevé ne suffit-il pas à rejeter un programme ?','ainfer':'Parce qu’il doit être comparé aux bénéfices attendus, aux alternatives et au coût d’opportunité.','qassume':'Que suppose une valeur attendue informative ?','aassume':'Des probabilités et montants suffisamment défendables ainsi qu’une séparation des dommages qui ne doivent pas être noyés dans la moyenne.','qrelation':'Comment le texte répond-il au problème des pertes concentrées ?','arelation':'Il conserve le calcul mais ajoute explicitement la distribution et certaines contraintes séparées.','astance':'Utiliser un calcul transparent comme base, puis l’encadrer par distribution et réversibilité.','asummary':'La valeur attendue rend les hypothèses comparables sans remplacer les jugements sur qui supporte les pertes.'},
 {'id':'fr-c1-u08-p04','seq':46,'title':'Point de vue B : un bon plan doit survivre aux mauvaises surprises','genre':'scenario comparison','topics':['robustness','downside risk'],'pair':PAIR,'paras':["Le second point de vue se méfie d’une optimisation trop précise lorsque les probabilités sont elles-mêmes fragiles. Il préfère comparer ce qui arrive dans plusieurs scénarios plausibles, notamment lorsque l’environnement change d’une manière que le modèle avait mal représentée.","Cette approche ne cherche pas le résultat parfait dans le scénario moyen. Elle demande quelle option évite une défaillance difficile à corriger, conserve une marge de manœuvre et peut être adaptée lorsque de nouvelles informations arrivent.","Le meilleur contreargument est le coût de la prudence : une stratégie robuste peut abandonner une partie du bénéfice attendu. Le point de vue B répond que ce coût doit être comparé à la gravité et à l’irréversibilité du scénario défavorable, plutôt qu’étiqueté simplement comme inefficacité.","La conclusion recommande un tableau qui montre simultanément valeur attendue, scénario défavorable, capacité d’adaptation et seuil de révision. La robustesse complète alors la prévision lorsque l’incertitude du modèle est elle-même importante."],'qclaim':'Quelle priorité défend le point de vue B ?','aclaim':'Choisir une option qui reste acceptable sous plusieurs scénarios plausibles et conserve une capacité d’adaptation.','qinfer':'Pourquoi ne pas optimiser uniquement le scénario moyen ?','ainfer':'Parce que les probabilités ou le modèle peuvent être fragiles et qu’une défaillance grave peut être difficile à corriger.','qassume':'Que suppose une stratégie robuste utile ?','aassume':'Que les scénarios défavorables restent plausibles et que la marge conservée ait une valeur réelle pour l’adaptation.','qrelation':'Comment le texte répond-il au coût de la prudence ?','arelation':'Il compare le bénéfice abandonné avec la gravité et l’irréversibilité des pertes évitées.','astance':'Compléter la valeur attendue par robustesse, scénario défavorable et adaptabilité.','asummary':'Une décision robuste accepte parfois moins de gain moyen pour éviter une défaillance grave et préserver la révision.','across':'A privilégie une comparaison explicite des valeurs attendues puis ajoute des contraintes; B donne davantage de poids à la robustesse lorsque les probabilités et le modèle sont eux-mêmes incertains.'},
 {'id':'fr-c1-u08-p05','seq':47,'title':'Ce que le modèle laisse de côté doit rester dans la décision','genre':'analysis','topics':['residual risk','stress tests'],'paras':["Un dernier scénario fictif teste un plan de capacité. Le modèle central prévoit une utilisation moyenne confortable, mais quelques périodes rapprochent le système de sa limite. La question n’est pas seulement de savoir si la moyenne est correcte : il faut examiner le risque résiduel lorsque plusieurs erreurs se combinent.","L’analyse sépare capacité nominale, capacité réellement disponible et demande incertaine. Elle simule ensuite une baisse de ressource, un pic temporaire et un retard de réparation. Aucun de ces événements n’est présenté comme certain; leur fonction est d’éprouver la fragilité du plan.","Le contreargument affirme qu’empiler des scénarios défavorables peut produire une image artificiellement pessimiste. Le rapport répond en limitant les stress tests à des combinaisons plausibles et en indiquant leur fréquence historique ou leur mécanisme, lorsqu’une telle information existe dans le cas fictif.","La recommandation retient une marge dont le coût est explicite et une règle de révision. Si l’utilisation réelle s’écarte durablement du modèle, la marge peut être réduite ou augmentée. Le risque résiduel n’est donc ni ignoré ni transformé en peur illimitée."],'qclaim':'Pourquoi la moyenne du modèle ne suffit-elle pas ?','aclaim':'Parce que la décision doit aussi examiner les périodes proches de la limite et les combinaisons plausibles d’erreurs.','qinfer':'Quel est le rôle d’un stress test ?','ainfer':'Tester la fragilité du plan sous une condition défavorable plausible, non prédire qu’elle arrivera.','qassume':'Que suppose un stress test défendable ?','aassume':'Des scénarios reliés à un mécanisme ou une plausibilité plutôt qu’une accumulation arbitraire de catastrophes.','qrelation':'Comment le rapport répond-il à l’objection de pessimisme ?','arelation':'Il limite les combinaisons aux scénarios plausibles et rend leur coût de protection explicite.','astance':'Conserver une marge mesurée et révisable face au risque résiduel.','asummary':'Le modèle central est complété par des scénarios de capacité afin que les erreurs plausibles et leur coût de protection restent visibles.'}]
def checkpoint(groups,deck,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]];ps=["Le checkpoint rassemble horizon, quantité, valeur, scénario et risque résiduel dans une décision fictive. Une organisation doit choisir entre trois plans dont les coûts, bénéfices et délais diffèrent. Aucun plan n’est dominant sur toutes les dimensions, et plusieurs probabilités restent incertaines.","Le lecteur commence par séparer ce qui est mesuré de ce qui est prévu. Il identifie ensuite les seuils qui transforment une quantité en action, les hypothèses nécessaires pour comparer les valeurs et les groupes qui supportent les pertes dans chaque option.","Deux analyses sont ensuite confrontées : un calcul de valeur attendue et un test de robustesse. Leur désaccord n’est pas résolu par une moyenne supplémentaire; il faut décider combien coûte la marge, quelle perte serait difficile à corriger et quelle nouvelle donnée modifierait les probabilités.","La synthèse choisit provisoirement un plan et annonce un calendrier de révision. Une bonne prévision n’élimine donc pas le jugement : elle rend les conditions, les alternatives et les conséquences suffisamment explicites pour que ce jugement puisse être critiqué et corrigé."];ps[1]+=' Révision cumulative : '+'; '.join(f'« {f} »' for f in forms)+'.';ps,text=fit(ps,lo,hi);P=base.prior(prior);rev=[base.rev(f,P) for f in forms];ids={t['form']:t['id'] for t in rev};items=[('main_claim','Quelle tâche organise le checkpoint ?','Choisir sous incertitude en reliant horizon, quantité, valeur, scénarios et révision.',[forms[0]]),('inference','Pourquoi séparer mesure et prévision ?','Pour distinguer ce qui est observé maintenant de ce qui dépend d’un modèle futur.',[forms[1]]),('assumption','Que suppose une comparaison de valeur ?','Des unités, horizons et probabilités suffisamment comparables.',[forms[8]]),('argument_relation','Comment valeur attendue et robustesse sont-elles reliées ?','Elles éclairent des dimensions différentes et sont comparées par le coût des marges et des pertes.',[forms[12]]),('stance','Quelle position analytique domine ?','Rendre hypothèses, distributions et règles de révision explicites.',[forms[16]]),('summary','Résume le checkpoint.','Comparer des scénarios, quantifier ce qui peut l’être, protéger contre les pertes pertinentes et annoncer quand réviser.',[forms[19]]),('vocabulary_in_context',f'Quel rôle joue « {forms[3]} » ?',USE[forms[3]],[forms[3]]),('vocabulary_in_context',f'Quel rôle joue « {forms[10]} » ?',USE[forms[10]],[forms[10]]),('vocabulary_in_context',f'Quel rôle joue « {forms[14]} » ?',USE[forms[14]],[forms[14]]),('synthesis','Quelle règle se transfère à un nouveau problème ?','Une décision robuste relie la précision disponible au coût du délai, aux erreurs possibles et à une condition de révision.',[forms[6],forms[18]])];q,a=base.qa(items,ids)
 return {'id':'fr-c1-u08-p06','language':'fr','cefr':'C1','unit':8,'sequence':48,'revision':1,'title':'Checkpoint : prévoir sans confondre modèle et décision','passage_type':'checkpoint','genre':'briefing','domains':['professional','public'],'topics':[theme,'cumulative forecasting'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c1-u08-p06-g1','role':'integration','description':'integrate conditionality, comparison and forecast scope'}],'discourse_targets':[{'id':'fr-c1-u08-p06-d1','role':'integration','description':'synthesize horizon, probability, value, robustness and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C1 Unit08 zero-new checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Zero-new forecasting checkpoint.']},'paired_text_group':None,'prerequisites':['French C1 Unit08 P01-P05'],'difficulty_notes_internal':'C1 cumulative forecasting/risk reasoning.','reader_tags':['unit_role:checkpoint','generation_batch','french_c1_u08']}
def main():
 raw=C1.read_text(encoding='utf-8');rows=[json.loads(x) for x in raw.splitlines() if x.strip()];l=json.loads(LOCK.read_text());p=json.loads(PLAN.read_text());s=json.loads(SEL.read_text());c=h(C1);b=h(B2)
 if len(rows)!=42 or l.get('status')!='PASS' or l.get('c1_canonical_blob')!=c or l.get('b2_canonical_blob')!=b:raise AssertionError('Unit08 source mismatch')
 if p.get('c1_source_blob')!=c or s.get('c1_source_blob')!=c:raise AssertionError('Unit08 plan/selection stale')
 groups=s['passage_groups'];r=l['unit07_target_groups'];reviews={k:r[k] for k in ['p01','p02','p03','p04','p05']};deck=base.deck();lo,hi=s['word_band'];unit=[mk(x,groups[x['id'][-3:]],reviews[x['id'][-3:]],rows,deck,lo,hi,p['theme']) for x in specs()];unit.append(checkpoint(groups,deck,lo,hi,p['theme'],rows+unit));V=Draft202012Validator(json.loads(SCHEMA.read_text()))
